def balanced_call_contents(text: str, marker: str):
    start = 0
    while True:
        marker_at = text.find(marker, start)
        if marker_at < 0:
            return
        open_at = marker_at + len(marker) - 1
        depth = 0
        in_string = False
        escaped = False
        for index in range(open_at, len(text)):
            char = text[index]
            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
                continue
            if char == '"':
                in_string = True
            elif char == "(":
                depth += 1
            elif char == ")":
                depth -= 1
                if depth == 0:
                    yield marker_at, index + 1, text[open_at + 1 : index]
                    start = index + 1
                    break
        else:
            raise RuntimeError(f"unterminated {marker} occurrence at {marker_at}")


def split_top_level_arguments(contents: str) -> list[str]:
    result: list[str] = []
    start = 0
    depth = 0
    in_string = False
    escaped = False
    for index, char in enumerate(contents):
        if in_string:
